// Client-side post search, generated by Parrot at build time. The index
// below is a trie of every published post's title, tag and category words;
// nothing is fetched at runtime. Restyle it through the .search* classes.
(function () {
  var INDEX = /*__PARROT_SEARCH_INDEX__*/null;
  var LIMIT = /*__PARROT_SEARCH_LIMIT__*/10;
  var POSTS_KEY = '$';

  // Same normalisation as Parrot::SearchIndex.tokenize: lowercase, then runs
  // of letters, combining marks and digits.
  function tokenize(text) {
    return String(text || '').toLowerCase().match(/[\p{L}\p{M}\p{N}]+/gu) || [];
  }

  // Every post id under the trie node `token` leads to, or null when no
  // indexed word starts with it.
  function idsWithPrefix(token) {
    var node = INDEX.trie;
    for (var i = 0; i < token.length; i++) {
      node = node[token[i]];
      if (!node) return null;
    }

    var ids = {};
    var stack = [node];
    while (stack.length) {
      var current = stack.pop();
      Object.keys(current).forEach(function (key) {
        if (key === POSTS_KEY) {
          current[key].forEach(function (id) { ids[id] = true; });
        } else {
          stack.push(current[key]);
        }
      });
    }
    return ids;
  }

  // The posts ({ title, url }) matching every word of `query` as a prefix,
  // each once, newest first, at most LIMIT of them. [] for an empty query.
  function search(query) {
    var tokens = tokenize(query);
    if (!INDEX || tokens.length === 0) return [];

    var matches = null;
    for (var i = 0; i < tokens.length; i++) {
      var ids = idsWithPrefix(tokens[i]);
      if (!ids) return [];
      if (matches) {
        Object.keys(matches).forEach(function (id) { if (!ids[id]) delete matches[id]; });
      } else {
        matches = ids;
      }
    }

    return Object.keys(matches)
      .map(Number)
      .sort(function (a, b) { return a - b; })
      .slice(0, LIMIT)
      .map(function (id) { return INDEX.posts[id]; });
  }

  window.ParrotSearch = { search: search };

  function setup() {
    var container = document.querySelector('.search');
    if (!container) return;
    var input = container.querySelector('.search-input');
    var list = container.querySelector('.search-suggestions');
    if (!input || !list) return;

    var results = [];
    var active = -1;

    list.id = list.id || 'search-suggestions';
    input.setAttribute('role', 'combobox');
    input.setAttribute('aria-autocomplete', 'list');
    input.setAttribute('aria-controls', list.id);
    input.setAttribute('aria-expanded', 'false');

    function close() {
      list.hidden = true;
      list.innerHTML = '';
      results = [];
      active = -1;
      input.setAttribute('aria-expanded', 'false');
      input.removeAttribute('aria-activedescendant');
    }

    function highlight(index) {
      var items = list.querySelectorAll('.search-suggestion');
      active = index;
      for (var i = 0; i < items.length; i++) {
        var on = i === index;
        items[i].classList.toggle('is-active', on);
        items[i].setAttribute('aria-selected', on ? 'true' : 'false');
      }
      if (index >= 0 && items[index]) {
        input.setAttribute('aria-activedescendant', items[index].id);
        items[index].scrollIntoView({ block: 'nearest' });
      } else {
        input.removeAttribute('aria-activedescendant');
      }
    }

    function render() {
      var query = input.value;
      if (tokenize(query).length === 0) return close();

      results = search(query);
      active = -1;
      list.innerHTML = '';

      if (results.length === 0) {
        var empty = document.createElement('li');
        empty.className = 'search-empty';
        empty.textContent = 'No matching posts';
        list.appendChild(empty);
      }

      results.forEach(function (post, index) {
        var item = document.createElement('li');
        item.className = 'search-suggestion';
        item.id = list.id + '-' + index;
        item.setAttribute('role', 'option');
        item.setAttribute('aria-selected', 'false');
        var link = document.createElement('a');
        link.href = post.url;
        link.textContent = post.title;
        link.tabIndex = -1;
        item.appendChild(link);
        item.addEventListener('mousemove', function () { if (active !== index) highlight(index); });
        list.appendChild(item);
      });

      list.hidden = false;
      input.setAttribute('aria-expanded', 'true');
      input.removeAttribute('aria-activedescendant');
    }

    input.addEventListener('input', render);
    input.addEventListener('focus', function () { if (input.value) render(); });

    input.addEventListener('keydown', function (event) {
      if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
        if (results.length === 0) return;
        event.preventDefault();
        var step = event.key === 'ArrowDown' ? 1 : -1;
        highlight((active + step + results.length) % results.length);
      } else if (event.key === 'Enter') {
        var post = results[active >= 0 ? active : 0];
        if (!post) return;
        event.preventDefault();
        window.location.href = post.url;
      } else if (event.key === 'Escape') {
        input.value = '';
        close();
      }
    });

    document.addEventListener('click', function (event) {
      if (!container.contains(event.target)) close();
    });

    container.hidden = false;
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', setup);
  } else {
    setup();
  }
})();
